MOTIF_NAME = 'king_safety_pawn_storm'
MOTIF_DESCRIPTION = 'The side to move has more pawns on the wing where the opponent king is located than the opponent has on the side-to-move king wing, indicating a pawn storm advantage.'
def motif(fen: str) -> bool:
    import chess
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    opp_king_sq = board.king(opp)
    if opp_king_sq is None:
        return False
    stm_king_sq = board.king(stm)
    if stm_king_sq is None:
        return False

    opp_kf = chess.square_file(opp_king_sq)
    stm_kf = chess.square_file(stm_king_sq)

    def wing_pawns(color, king_file):
        count = 0
        for sq in board.pieces(chess.PAWN, color):
            f = chess.square_file(sq)
            r = chess.square_rank(sq)
            if king_file <= 3:
                if f <= 3:
                    count += 1
            else:
                if f >= 4:
                    count += 1
        return count

    stm_storm = wing_pawns(stm, opp_kf)
    opp_storm = wing_pawns(opp, stm_kf)

    return stm_storm > opp_storm
